('suttru:chennai-marina', 'Marina Beach', 'chennai-marina', 'PLACE', 'BEACH', 'Chennai', 'Tamil Nadu', 13.051389, 80.283889, 'A Bay of Bengal beach on Chennai’s seafront.', 'A Bay of Bengal beach on Chennai’s seafront. Location source: https://geographic.org/geographic_names/name.php?c=india&fid=2690&uni=9093708. Map pin identifies the site; confirm the entrance or meeting point with the operator.', 'https://chennai.nic.in/tourist-place/marina/', 'UNKNOWN', 'UNKNOWN', NULL, 'Chennai District Administration', 'https://chennai.nic.in/tourist-place/marina/', '2026-10-12 16:14:00', '2026-11-11 16:14:00', 0.9, 1);
INSERT INTO discovery_items (external_id,name,slug,item_type,category,city,state,latitude,longitude,short_description,detailed_description,official_website,price_status,price_type,base_price,source_name,source_url,source_last_checked_at,verification_expires_at,confidence_score,enabled) VALUES
('suttru:chennai-museum', 'Government Museum, Chennai', 'chennai-museum', 'PLACE', 'MUSEUM', 'Chennai', 'Tamil Nadu', 13.07128, 80.25675, 'Explore the museum in Egmore, including its bronze and archaeology collections.', 'Explore the museum in Egmore, including its bronze and archaeology collections. Location source: https://mapcarta.com/W1126975457. Map pin identifies the site; confirm the entrance or meeting point with the operator.', 'https://chennai.nic.in/tourist-place/government-museum/', 'UNKNOWN', 'UNKNOWN', NULL, 'Chennai District Administration', 'https://chennai.nic.in/tourist-place/government-museum/', '2026-10-12 16:14:00', '2026-11-11 16:14:00', 0.9, 1);
INSERT INTO discovery_items (external_id,name,slug,item_type,category,city,state,latitude,longitude,short_description,detailed_description,official_website,price_status,price_type,base_price,source_name,source_url,source_last_checked_at,verification_expires_at,confidence_score,enabled) VALUES
('suttru:chennai-muttukadu', 'Muttukadu Boat House boating', 'chennai-muttukadu', 'ACTIVITY', 'ADVENTURE', 'Chennai', 'Tamil Nadu', 12.8058083, 80.2419194, 'TTDC boating at Muttukadu, south of Chennai. Confirm boat type, passenger limits and weather availability with the operator.', 'TTDC boating at Muttukadu, south of Chennai. Confirm boat type, passenger limits and weather availability with the operator. Location source: https://en.wikipedia.org/wiki/Muttukadu_boat_house. Map pin identifies the site; confirm the entrance or meeting point with the operator. Approximately 36 km from central Chennai; increase the search radius to 50 km. Published starting prices do not specify a comparable per-person unit, so pricing remains unverified.', 'https://www.ttdc.in/', 'UNKNOWN', 'UNKNOWN', NULL, 'Tamil Nadu Tourism Development Corporation', 'https://www.ttdc.in/', '2026-10-12 16:14:00', '2026-11-11 16:14:00', 0.9, 1);
INSERT INTO discovery_items (external_id,name,slug,item_type,category,city,state,latitude,longitude,short_description,detailed_description,official_website,price_status,price_type,base_price,source_name,source_url,source_last_checked_at,verification_expires_at,confidence_score,enabled) VALUES
('suttru:mysuru-palace', 'Mysuru Palace', 'mysuru-palace', 'PLACE', 'HISTORICAL', 'Mysuru', 'Karnataka', 12.305135, 76.655148, 'Visit the Amba Vilas Palace and its historic halls. Check current admission and access with the palace before travel.', 'Visit the Amba Vilas Palace and its historic halls. Check current admission and access with the palace before travel. Location source: https://mysore.nic.in/en/tourist-place/mysuru-palace/. Map pin identifies the site; confirm the entrance or meeting point with the operator.', 'https://mysore.nic.in/en/tourist-place/mysuru-palace/', 'UNKNOWN', 'UNKNOWN', NULL, 'Mysuru District Administration', 'https://mysore.nic.in/en/tourist-place/mysuru-palace/', '2026-10-12 16:14:00', '2026-11-11 16:14:00', 0.9, 1);
