('suttru:mysuru-zoo', 'Mysuru Zoo', 'mysuru-zoo', 'PLACE', 'WILDLIFE', 'Mysuru', 'Karnataka', 12.3022057, 76.6641882, 'Visit Sri Chamarajendra Zoological Gardens. Admission prices below exclude parking, camera charges and battery vehicle rides.', 'Visit Sri Chamarajendra Zoological Gardens. Admission prices below exclude parking, camera charges and battery vehicle rides. Location source: https://www.mysuruzoo.info/visit. Map pin identifies the site; confirm the entrance or meeting point with the operator.', 'https://www.mysuruzoo.info/visit', 'VERIFIED', 'PER_PERSON', 120, 'Mysuru Zoo', 'https://www.mysuruzoo.info/visit', '2026-10-12 16:14:00', '2026-11-11 16:14:00', 0.9, 1);
INSERT INTO discovery_items (external_id,name,slug,item_type,category,city,state,latitude,longitude,short_description,detailed_description,official_website,price_status,price_type,base_price,source_name,source_url,source_last_checked_at,verification_expires_at,confidence_score,enabled) VALUES
('suttru:mysuru-karanji', 'Karanji Lake birdwatching', 'mysuru-karanji', 'ACTIVITY', 'NATURE', 'Mysuru', 'Karnataka', 12.302778, 76.673611, 'A self-guided birdwatching visit at Karanji Lake. Prices cover lake admission only; no guide, boat ride or equipment is included.', 'A self-guided birdwatching visit at Karanji Lake. Prices cover lake admission only; no guide, boat ride or equipment is included. Location source: https://mysore.nic.in/en/tourist-place/karanji-lake/. Map pin identifies the site; confirm the entrance or meeting point with the operator. Activity source: https://www.incredibleindia.gov.in/en/karnataka/mysuru/mysuru-zoo. The operator tariff is used instead of the district page’s older fee table.', 'https://www.mysuruzoo.info/visit', 'VERIFIED', 'PER_PERSON', 60, 'Mysuru Zoo', 'https://www.mysuruzoo.info/visit', '2026-10-12 16:14:00', '2026-11-11 16:14:00', 0.9, 1);
